import json
d = json.load(open('/app/resources/treasury_bulletin_2013_06.json'))
pages = d.get('document', {}).get('pages', [])
# Search for Dec 31, 2013 in all pages
for i, page in enumerate(pages):
    if 'elements' in page:
        for el in page['elements']:
            if 'text' in el:
                text = el.get('text', '')
                if 'Dec. 31, 2013' in text or 'December 31, 2013' in text:
                    print(f'Page {i}:', text[:200])
